CREATE TABLE mysql_databases(id TEXT PRIMARY KEY CHECK(length(id)=32),workspace_id TEXT NOT NULL,organization_id TEXT NOT NULL,name TEXT NOT NULL,destination_id TEXT NOT NULL,destination_digest TEXT NOT NULL,database_name TEXT NOT NULL,runtime_role TEXT NOT NULL,credential_reference TEXT NOT NULL UNIQUE,state TEXT NOT NULL CHECK(state IN ('active','failed')),revision INTEGER NOT NULL DEFAULT 1,disconnected INTEGER NOT NULL DEFAULT 0,checked_at TEXT,FOREIGN KEY(workspace_id,organization_id) REFERENCES workspaces(id,organization_id));
CREATE INDEX idx_mysql_workspace ON mysql_databases(workspace_id,organization_id);
